#include "postquantiquecoin/wallet/WalletRecoveryFile.h"
#include "postquantiquecoin/core/Serialization.h"
namespace pqc { std::vector<uint8_t> WalletRecoveryFile::Serialize() const{ Serializer s; s.String("PQCRECOVERY"); s.U32(version); s.Bytes(kemPublicKey); s.Bytes(kemPrivateKey); s.Bytes(wrappedDek); return s.Data(); } Result<WalletRecoveryFile> WalletRecoveryFile::Deserialize(const std::vector<uint8_t>& data){ Deserializer d(data); WalletRecoveryFile f; auto m=d.String(); if(m.IsErr()||m.Value()!="PQCRECOVERY") return Result<WalletRecoveryFile>::Err("bad recovery file magic"); auto v=d.U32(); if(v.IsErr()) return Result<WalletRecoveryFile>::Err(v.Error()); f.version=v.Value(); auto pk=d.Bytes(); if(pk.IsErr()) return Result<WalletRecoveryFile>::Err(pk.Error()); f.kemPublicKey=pk.Value(); auto sk=d.Bytes(); if(sk.IsErr()) return Result<WalletRecoveryFile>::Err(sk.Error()); f.kemPrivateKey=sk.Value(); auto w=d.Bytes(); if(w.IsErr()) return Result<WalletRecoveryFile>::Err(w.Error()); f.wrappedDek=w.Value(); return Result<WalletRecoveryFile>::Ok(f); } }
